import java.util.*; public class MovieReviewProfiler{static void classifyWordLengths(String s){int a=0,b=0,c=0;for(String w:s.trim().split("\\s+")){int n=w.replaceAll("[^A-Za-z]","").length();if(n<=4&&n>0)a++;else if(n<=8)b++;else c++;}System.out.println("Short: "+a+" | Medium: "+b+" | Long: "+c);}public static void main(String[] z){classifyWordLengths(new Scanner(System.in).nextLine());}}